function formatScheduledTime(value){if(!value)return "";const d=new Date(value);return Number.isNaN(d.getTime())?"":d.toLocaleString("es-ES",{dateStyle:"medium",timeStyle:"short"});}
function localDateTimeValue(date){const pad=n=>String(n).padStart(2,"0");return date.getFullYear()+"-"+pad(date.getMonth()+1)+"-"+pad(date.getDate())+"T"+pad(date.getHours())+":"+pad(date.getMinutes());}
function openBooking(mode){bookingMode=mode;const field=$("#scheduled-for"),wrap=$("#scheduled-fields");$("#booking-title").textContent=mode==="scheduled"?"Reserva tu taxi":"Pide tu taxi";$("#send-ride").textContent=mode==="scheduled"?"Reservar taxi":"Solicitar taxi";wrap.classList.toggle("hidden",mode!=="scheduled");field.required=mode==="scheduled";if(mode==="scheduled"){const min=new Date(Math.ceil((Date.now()+15*60*1000)/60000)*60000);field.min=localDateTimeValue(min);field.max=localDateTimeValue(new Date(Date.now()+90*24*60*60*1000));if(!field.value||new Date(field.value).getTime()<min.getTime())field.value=localDateTimeValue(min)}else{field.required=false;field.value="";}show("booking");restoreBookingDetails();}
function saveBookingDetails(name,phone){try{localStorage.setItem("taxiLocalBookingDetails",JSON.stringify({name:String(name||""),phone:String(phone||"")}))}catch(_){}}
function normalizePhone(value){const digits=String(value||"").replace(/\D/g,"");if(digits.length===9)return "+34"+digits;if(digits.length===11&&digits.startsWith("34"))return "+"+digits;return String(value||"").trim().replace(/[\s().-]/g,"")}
function normalizeSpanishPhone(value){return String(value||"").replace(/\D/g,"").replace(/^34(?=\d{9}$)/,"")}
function restoreBookingDetails(){try{const saved=JSON.parse(localStorage.getItem("taxiLocalBookingDetails")||"{}");const form=$("#ride-form");if(!form)return;const name=form.elements.namedItem("customer_name"),phone=form.elements.namedItem("customer_phone");if(name&&!name.value&&saved.name)name.value=saved.name;if(phone&&!phone.value&&saved.phone)phone.value=saved.phone;if(customerUser){if(name&&!name.value)name.value=customerUser.username||customerUser.full_name||"";if(phone&&!phone.value&&customerUser.phone)phone.value=customerUser.phone}}catch(error){console.warn("No se pudieron restaurar los datos de reserva:",error)}}

const show=(name)=>{screens.forEach(s=>s.classList.toggle("active",s.id===name));$$(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.screen===name));window.scrollTo({top:0,behavior:"smooth"})};
function errText(e){let m=String(e?.message||e?.error_description||e?.error||e||"Error desconocido");if(/Edge Function returned a non-2xx status code/i.test(m)&&e?.context){try{const ctx=e.context;if(ctx&&typeof ctx.clone==="function"){ctx.clone().json().then(body=>{const detail=body?.error||body?.message||body?.msg||body?.details||body?.hint;if(detail){const target=document.querySelector("#driver-message");if(target){target.textContent=detail;target.className="message error"}}}).catch(()=>{})}}catch(_){}}if(/Invalid API key|Invalid JWT/i.test(m))return "La clave de conexión no ha sido aceptada. Comprueba config.js y la clave pública del proyecto.";if(/row-level security|permission denied|not allowed/i.test(m))return "La base de datos ha rechazado la acción por seguridad. Revisa las políticas RLS.";if(/Email not confirmed/i.test(m))return "Este correo todavía no está confirmado. Revisa tu bandeja de entrada o pide al administrador que confirme la cuenta desde el panel; no hace falta desactivar la seguridad.";if(/duplicate key/i.test(m))return "Ya existe un perfil para esta cuenta.";return "No se ha podido completar la operación: "+m}
if(!db){document.body.insertAdjacentHTML("afterbegin",'<div class="config-error">No se pudo cargar la conexión. Revisa config.js.</div>');return}
