$("#customer-auth-form").addEventListener("submit",async e=>{e.preventDefault();const form=e.currentTarget, f=new FormData(form),mode=form.dataset.mode||"login",btn=$("#customer-auth-submit");const password=String(f.get("password")||""),username=String(f.get("username")||"").trim().toLowerCase(),identifier=String(f.get("identifier")||"").trim(),phone=mode==="signup"?normalizeSpanishPhone(f.get("signup_phone")):identifier;btn.disabled=true;btn.textContent=mode==="signup"?"Creando cuenta…":"Entrando…";message($("#customer-message"),"");try{if(mode==="signup"){if(!/^[a-z0-9_]{3,24}$/.test(username))throw new Error("El nombre de usuario debe tener 3-24 caracteres: letras, números o guion bajo.");if(phone.replace(/\D/g,"").length!==9)throw new Error("Introduce un teléfono español de 9 cifras, sin +34.");const {data,error}=await db.functions.invoke("customer-auth",{body:{action:"signup",username,phone,password}});if(error){let detail="";try{const response=error.context;const body=response&&typeof response.clone==="function"?await response.clone().json():{};detail=body.error||body.message||body.msg||body.details||body.hint||""}catch(_){}throw new Error(detail||error.message||"No se pudo completar el registro de cliente.")}if(data?.error)throw new Error(data.error);if(!data.email)throw new Error("No se pudo completar el registro.");const {error:loginError}=await db.auth.signInWithPassword({email:data.email,password});if(loginError)throw loginError;saveBookingDetails(username,"+34"+phone);await syncCustomer();if(customerUser)show("home");message($("#customer-message"),"Cuenta creada. Ya puedes pedir o reservar tu taxi desde Inicio.","success")}else{const {data,error}=await db.functions.invoke("customer-auth",{body:{action:"login",identifier,password}});if(error){let detail="";try{const response=error.context;const body=response&&typeof response.clone==="function"?await response.clone().json():{};detail=body.error||body.message||body.msg||body.details||body.hint||""}catch(_){}throw new Error(detail||error.message||"No se pudo iniciar sesión como cliente.")}if(data?.error)throw new Error(data.error);if(!data.email)throw new Error("No se pudo iniciar sesión.");const {error:loginError}=await db.auth.signInWithPassword({email:data.email,password});if(loginError)throw loginError;await syncCustomer();if(customerUser){show("home");message($("#customer-message"),"Sesión iniciada. Ya puedes pedir o reservar tu taxi desde Inicio.","success")}else message($("#customer-message"),"No se pudo cargar el perfil de cliente.","error")}}catch(err){message($("#customer-message"),await errText(err),"error")}finally{btn.disabled=false;btn.textContent=(form.dataset.mode||"login")==="signup"?"Crear cuenta":"Iniciar sesión"}});
