$("#customer-edit-profile").addEventListener("click",async()=>{if(!customerUser)return;const full_name=prompt("Nombre completo",customerUser.full_name);if(full_name===null)return;const phone=prompt("Teléfono de contacto",customerUser.phone);if(phone===null)return;const normalized=normalizePhone(phone);if(full_name.trim().length<2||normalized.replace(/\D/g,"").length<9)return message($("#customer-message"),"Revisa el nombre y el teléfono.","error");const {data,error}=await db.from("customer_profiles").update({full_name:full_name.trim(),phone:normalized,updated_at:new Date().toISOString()}).eq("user_id",customerUser.id).select("user_id,full_name,phone").single();if(error)return message($("#customer-message"),errText(error),"error");customerUser={...data,id:customerUser.id,email:customerUser.email};restoreBookingDetails();await syncCustomer();message($("#customer-message"),"Datos actualizados.","success")});
