async function submitRide(e){
 e.preventDefault();const form=e.currentTarget,btn=$("#send-ride")||form.querySelector('[type="submit"]'),f=new FormData(form);
 if(window.__taxiRideBusy)return;window.__taxiRideBusy=true;if(btn){btn.disabled=true;btn.textContent="Guardando reserva…"}
 message(bookingMessage,"Guardando tu solicitud…");
 try{
  const payload={customer_name:String(f.get("customer_name")||"").trim(),customer_phone:String(f.get("customer_phone")||"").trim(),pickup_town:String(f.get("pickup_town")||"Elda"),pickup_address:String(f.get("pickup_address")||"").trim(),destination:String(f.get("destination")||"").trim(),passengers:Number(f.get("passengers")||1),notes:String(f.get("notes")||"").trim()};
  if(bookingMode==="scheduled"){const localValue=String(f.get("scheduled_for_local")||"").trim();if(!localValue)throw new Error("Elige la fecha y hora de recogida.");const chosen=new Date(localValue);if(!Number.isFinite(chosen.getTime())||chosen.getTime()<Date.now()+15*60*1000)throw new Error("Elige una hora que sea al menos 15 minutos posterior a la hora actual.");if(chosen.getTime()>Date.now()+90*24*60*60*1000)throw new Error("Solo puedes reservar con hasta 90 días de antelación.");payload.scheduled_for=chosen.toISOString()}else payload.scheduled_for=null;
  if(payload.customer_phone.replace(/\D/g,"").length<9)throw new Error("Introduce un teléfono válido para que el taxista pueda llamarte.");
  const {data,error}=await db.functions.invoke("create-ride",{body:payload});
  if(error){let detail="";try{detail=(await error.context?.json())?.error||""}catch(_){}throw new Error(detail||error.message||"No se pudo contactar con el servicio de reservas.")}
  if(data?.error)throw new Error(data.error);if(!data?.ride?.id)throw new Error("El servidor no confirmó el identificador de la reserva.");
  const ride=data.ride;lastPickupTown=ride.pickup_town;
  const guestKey="taxiLocalGuestRides";let guest=[];try{guest=JSON.parse(localStorage.getItem(guestKey)||"[]")}catch(_){}
  if(!customerUser){guest.unshift(ride);localStorage.setItem(guestKey,JSON.stringify(guest.slice(0,30)))}
  saveBookingDetails(payload.customer_name,payload.customer_phone);
  if(customerUser)await loadCustomerRides();else await loadCustomerRides();
  await loadCustomerReservationMap();
  message(bookingMessage,bookingMode==="scheduled"?"Reserva anticipada guardada. La hora solicitada aparece en Mis reservas y el taxista podrá aceptarla.":"Reserva guardada. Aquí puedes ver tus solicitudes y llamar a los taxis disponibles.","success");
  form.reset();restoreBookingDetails();
  show("customer-reservations");
 }catch(err){message(bookingMessage,await errText(err),"error")}
 finally{if(btn){btn.disabled=false;btn.textContent=bookingMode==="scheduled"?"Reservar taxi":"Solicitar taxi"}window.__taxiRideBusy=false}
}

$("#use-location").addEventListener("click",()=>{
 const button=$("#use-location"),field=$("#pickup-address");
 if(!navigator.geolocation){message(locationMessage,"Este navegador no permite compartir la ubicación. Escribe la dirección manualmente.","error");return}
 button.disabled=true;button.textContent="Obteniendo ubicación…";message(locationMessage,"Solicitando permiso de ubicación…");
 navigator.geolocation.getCurrentPosition(pos=>{
  const lat=pos.coords.latitude,lon=pos.coords.longitude;
  field.value="https://maps.google.com/?q="+lat+","+lon;
  lastPickupTown=String($("#ride-form").elements.namedItem("pickup_town").value||"Elda");
  message(locationMessage,"Ubicación exacta guardada. El conductor verá el punto de recogida en el mapa.","success");
  button.textContent="📍 Ubicación compartida";button.disabled=false;
 },err=>{
  message(locationMessage,err.code===1?"Permiso denegado. Activa la ubicación para Safari en Ajustes o escribe la dirección manualmente.":"No se pudo obtener la ubicación. Comprueba el GPS y vuelve a intentarlo.","error");
  button.textContent="📍 Compartir mi ubicación actual";button.disabled=false;
 },{enableHighAccuracy:true,timeout:20000,maximumAge:0});
});
