async function handleAuthSubmit(e){if(e?.preventDefault)e.preventDefault();if(window.__taxiAuthBusy)return;window.__taxiAuthBusy=true;const form=$("#auth-form");const f=new FormData(form),password=String(f.get("password")),btn=$("#auth-submit");btn.disabled=true;btn.textContent=authMode==="signup"?"Creando cuenta…":"Comprobando acceso…";message(driverMessage,authMode==="signup"?"Creando cuenta…":"Comprobando usuario y contraseña…");try{if(authMode==="signup"){const username=String(f.get("username")||"").trim().toLowerCase(),phone=normalizePhone(f.get("signup_phone")),full_name=username,town=String(f.get("town")||"Elda");const {data,error}=await db.functions.invoke("driver-auth",{body:{action:"signup",username,phone,full_name,town,password}});if(error){let detail="";try{const response=error.context;const body=response&&typeof response.clone==="function"?await response.clone().json():{};detail=body.error||body.message||body.msg||body.details||body.hint||""}catch(_){}throw new Error(detail||error.message||"No se pudo contactar con el servicio de registro.");}if(data?.error)throw new Error(data.error);if(!data.email)throw new Error(data?.error||"El servidor no devolvió el identificador de acceso.");const {data:loginData,error:loginError}=await db.auth.signInWithPassword({email:data.email,password});if(loginError)throw new Error("La cuenta se creó, pero no se pudo iniciar sesión automáticamente: "+loginError.message);if(!loginData.session)throw new Error("La cuenta se creó, pero Supabase no abrió la sesión. Prueba a iniciar sesión con tu usuario y contraseña.");currentUser=loginData.user;show("home");await syncDriver();syncRoleNavigation();message(driverMessage,"Cuenta creada y sesión iniciada. Tu perfil queda pendiente de aprobación. El administrador debe aprobarla antes de activar la disponibilidad.","success");return}const identifier=String(f.get("phone")||"").trim();const normalizedIdentifier=normalizePhone(identifier);if(form.dataset.adminOnly==="true"){const digits=identifier.replace(/\D/g,"").replace(/^34(?=\d{9}$)/,"");if(digits.length!==9)throw new Error("Introduce el teléfono de administrador de 9 cifras, sin +34.");const adminEmail=digits==="641445360"?"salekbachirliman@gmail.com":"";if(!adminEmail)throw new Error("Teléfono o contraseña de administrador incorrectos.");const {data,error}=await db.auth.signInWithPassword({email:adminEmail,password});if(error)throw new Error("No se pudo iniciar sesión de administrador: "+error.message);currentUser=data.user;show("home");await syncDriver();syncRoleNavigation();return}else if(identifier.includes("@")||normalizedIdentifier==="+34641445360"){const adminEmail=identifier.includes("@")?identifier:"salekbachirliman@gmail.com";const {data,error}=await db.auth.signInWithPassword({email:adminEmail,password});if(error)throw error;currentUser=data.user;await syncDriver();return}const {data,error}=await db.functions.invoke("driver-auth",{body:{action:"login",identifier,password}});if(error){let detail="";try{const response=error.context;const body=response&&typeof response.clone==="function"?await response.clone().json():{};detail=body.error||body.message||body.msg||body.details||body.hint||""}catch(_){}throw new Error(detail||error.message||"No se pudo iniciar sesión como conductor.")}if(data?.error)throw new Error(data.error);if(!data.email)throw new Error("No se encontró el correo interno de esta cuenta.");const {data:loginData,error:loginError}=await db.auth.signInWithPassword({email:data.email,password});if(loginError)throw loginError;currentUser=loginData.user;show("home");await syncDriver();syncRoleNavigation()}catch(err){message(driverMessage,await errText(err),"error")}finally{btn.disabled=false;btn.textContent=authMode==="signup"?"Crear cuenta":"Entrar";window.__taxiAuthBusy=false}}
