$("#sms-verify-form").addEventListener("submit",async e=>{e.preventDefault();const btn=e.currentTarget.querySelector("button"),token=String(new FormData(e.currentTarget).get("token")||"").trim(),pending=window.pendingDriverSignup;if(!pending)return message(driverMessage,"Vuelve a crear la cuenta para solicitar un nuevo código SMS.","error");btn.disabled=true;try{const verified=await db.auth.verifyOtp({phone:pending.phone,token,type:"sms"});if(verified.error)throw verified.error;currentUser=verified.data.user;const {error}=await db.from("driver_profiles").upsert({user_id:currentUser.id,full_name:pending.full_name,phone:pending.phone,town:pending.town,status:"pending"},{onConflict:"user_id"});if(error)throw error;window.pendingDriverSignup=null;$("#sms-verify-form").classList.add("hidden");$("#auth-form").classList.remove("hidden");$("#auth-form").reset();authMode="login";$$("[data-auth]").forEach(t=>t.classList.toggle("selected",t.dataset.auth==="login"));$("#signup-fields").classList.add("hidden");$("#auth-submit").textContent="Entrar";message(driverMessage,"Teléfono verificado y perfil creado. La administración debe aprobar tu perfil antes de recibir reservas.","success");await syncDriver()}catch(err){message(driverMessage,errText(err),"error")}finally{btn.disabled=false}});
