async function loadCustomerReservationMap(){
 const mapEl=$("#customer-reservations-map"),list=$("#customer-local-drivers");if(!mapEl||!list)return;
 const town=lastPickupTown||"Elda";
 const {data,error}=await db.from("driver_profiles").select("user_id,username,full_name,phone,town,latitude,longitude").eq("status","approved").eq("is_available",true).not("latitude","is",null).not("longitude","is",null).in("town",[town,"Ambas"]).limit(50);
 if(error){list.innerHTML='<div class="empty-state">No se pudieron cargar los taxis disponibles.</div>';return}
 if(window.L){if(customerReservationsMap)customerReservationsMap.remove();customerReservationsMap=L.map("customer-reservations-map").setView(townCenters[town]||townCenters.Elda,13);L.tileLayer("https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png",{maxZoom:19,attribution:"© OpenStreetMap"}).addTo(customerReservationsMap);(data||[]).forEach(d=>{if(d.latitude!=null&&d.longitude!=null)L.marker([d.latitude,d.longitude],{icon:premiumTaxiPin()}).addTo(customerReservationsMap).bindPopup(escapeHtml(d.username||d.full_name||"Taxista"))});setTimeout(()=>customerReservationsMap&&customerReservationsMap.invalidateSize(),200)}
 list.innerHTML="";
 if(!data?.length){list.innerHTML='<div class="empty-state">No hay taxis disponibles en '+escapeHtml(town)+' ahora mismo.</div>';return}
 data.forEach(d=>{const el=document.createElement("article");el.className="ride-card";const h=document.createElement("h4");h.textContent=d.username||d.full_name||"Taxista";const p=document.createElement("p");p.textContent=d.town;const status=document.createElement("span");status.className="status";status.textContent="Disponible";el.append(h,p,status);const rawPhone=String(d.phone||"").trim();const phone=rawPhone.replace(/[^+0-9]/g,"");if(phone&&/[0-9]/.test(phone)){const call=document.createElement("a");call.className="primary call-driver";call.setAttribute("href","tel:"+phone);call.setAttribute("role","button");call.setAttribute("aria-label","Llamar directamente al conductor");call.innerHTML="<span aria-hidden='true'>📞</span> Llamar · "+escapeHtml(rawPhone);el.append(call)}else{const note=document.createElement("p");note.className="muted small";note.textContent="El teléfono de este conductor no está disponible.";el.append(note)}list.append(el)})
}

function formatLocationLabel(value){const raw=String(value||"").trim();if(!raw)return "📍 Ubicación no indicada";if(/https?:\/\//i.test(raw)||/maps\.google\.com/i.test(raw)){const cleaned=raw.replace(/https?:\/\/\S+/ig,"").replace(/maps\.google\.com\/\S*/ig,"").replace(/\bmapa\s*:?/ig,"").replace(/[—–|·,:\s]+$/g,"").trim();if(!cleaned||/^mi ubicación actual$/i.test(cleaned))return "📍 Mi ubicación";return "📍 "+cleaned+" · Ubicación"}return "📍 "+raw}
function escapeHtml(value){return String(value).replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]))}
