$("#availability-toggle").addEventListener("click",async()=>{
 const b=$("#availability-toggle"),accountMessage=$("#availability-message-account");
 if(!currentUser){message($("#availability-message"),"Inicia sesión como conductor para activar la disponibilidad.","error");return}
 if(b.disabled)return;b.disabled=true;b.textContent="Comprobando ubicación…";
 try{
  const {data:p,error}=await db.from("driver_profiles").select("town,is_available,status").eq("user_id",currentUser.id).single();if(error)throw error;
  if(p.status!=="approved"){const msg="Tu cuenta está pendiente de aprobación. El administrador debe aprobarla antes de activar la disponibilidad.";$("#availability-message").textContent=msg;if(accountMessage)accountMessage.textContent=msg;b.textContent="⏳ Pendiente de aprobación";return}
  if(p.is_available){const {error:e}=await db.from("driver_profiles").update({is_available:false,latitude:null,longitude:null,location_updated_at:null}).eq("user_id",currentUser.id);if(e)throw e;$("#availability-message").textContent="Disponibilidad desactivada. Ya no apareces en el mapa de clientes.";if(accountMessage)accountMessage.textContent="Estás fuera de servicio.";await syncDriver();return}
  if(!navigator.geolocation)throw new Error("Este navegador no permite compartir la ubicación. Abre Taxi Local en Safari.");
  $("#availability-message").textContent="Permite el acceso a la ubicación cuando Safari lo solicite.";
  const pos=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:20000,maximumAge:0}));
  const {error:e}=await db.from("driver_profiles").update({is_available:true,latitude:pos.coords.latitude,longitude:pos.coords.longitude,location_updated_at:new Date().toISOString()}).eq("user_id",currentUser.id).eq("status","approved");if(e)throw e;
  $("#availability-message").textContent="🟢 Disponibilidad activada. Tu taxi ya aparece en el mapa de clientes.";if(accountMessage)accountMessage.textContent="🟢 Estás disponible y visible para los clientes.";await syncDriver()
 }catch(err){const msg=err?.code===1?"No has permitido la ubicación. Actívala en Ajustes de Safari y vuelve a intentarlo.":err?.code===3?"La ubicación ha tardado demasiado. Comprueba el GPS y vuelve a intentarlo.":await errText(err);message($("#availability-message"),msg,"error");if(accountMessage)message(accountMessage,msg,"error")}
 finally{b.disabled=false;if(currentUser)await syncDriver().catch(()=>{})}
});

async function loadRides(){const list=$("#rides-list");list.innerHTML='<div class="empty-state">Cargando reservas…</div>';const {data,error}=await db.from("rides").select("id,customer_name,customer_phone,pickup_town,pickup_address,destination,passengers,notes,requested_at,scheduled_for,status,driver_id").order("created_at",{ascending:false}).limit(50);if(error){list.innerHTML="";message(driverMessage,errText(error),"error");return}if(!data?.length){list.innerHTML='<div class="empty-state">Todavía no hay reservas disponibles.</div>';return}list.innerHTML="";data.forEach(r=>{const c=document.createElement("article");c.className="ride-card";const h=document.createElement("h4");h.textContent=r.pickup_town+": "+formatLocationLabel(r.pickup_address);const d=document.createElement("p");d.textContent="Destino: "+r.destination;const scheduled=document.createElement("p");if(r.scheduled_for){scheduled.className="muted small";scheduled.textContent="Recogida programada: "+formatScheduledTime(r.scheduled_for)}const mapMatch=String(r.pickup_address||"").match(/https:\/\/maps\.google\.com\/\?q=[^\s]+/);if(mapMatch){const link=document.createElement("a");link.href=mapMatch[0];link.target="_blank";link.rel="noopener noreferrer";link.textContent="Abrir punto de recogida en el mapa ↗";link.className="map-link";const address=document.createElement("p");address.textContent="Punto de recogida: ubicación compartida";c.append(address,link)}const who=document.createElement("p");who.textContent=(r.customer_name?r.customer_name+" · ":"")+r.customer_phone+" · "+r.passengers+" pasajero(s)";if(r.scheduled_for)c.append(h,d,scheduled,who);else c.append(h,d,who);if(r.notes){const n=document.createElement("p");n.className="muted small";n.textContent="Nota: "+r.notes;c.append(n)}const st=document.createElement("span");st.className="status";st.textContent=({pending:"Pendiente",accepted:"Aceptada",completed:"Completada",cancelled:"Cancelada"})[r.status]||r.status;c.append(st);if(r.status==="pending"&&!r.driver_id){const b=document.createElement("button");b.className="primary";b.textContent="Aceptar reserva";b.onclick=async()=>{b.disabled=true;const {error}=await db.from("rides").update({status:"accepted",driver_id:currentUser.id}).eq("id",r.id).eq("status","pending").is("driver_id",null);if(error)message(driverMessage,errText(error),"error");else message(driverMessage,"Reserva aceptada.","success");await loadRides()};c.append(b)}else if(r.status==="accepted"&&r.driver_id===currentUser.id){const b=document.createElement("button");b.className="secondary";b.textContent="Marcar como completada";b.onclick=async()=>{b.disabled=true;const {error}=await db.from("rides").update({status:"completed"}).eq("id",r.id).eq("driver_id",currentUser.id);if(error)message(driverMessage,errText(error),"error");else message(driverMessage,"Servicio completado.","success");await loadRides()};c.append(b)}list.append(c)})}
